<?php
/** Topic, paginated replies, collections, owner actions and report workflow. */
use yii\helpers\Html;
$this->title=$model->title; $user=Yii::$app->user->identity; $canEdit=$user&&((int)$user->id===(int)$model->author_id||$user->isAdmin());
?>
<a class="back-link" href="/forum">← 球迷论坛</a><div class="forum-layout"><div><article class="thread-article"><div class="meta"><span><?= e($model->category?->name) ?></span><?php if($model->team): ?><a href="/teams/<?= e($model->team->slug) ?>"><?= \app\services\TeamUi::label($model->team) ?></a><?php endif ?><?php if($model->is_locked): ?><b class="badge">已锁定</b><?php endif ?><?php if($model->status!=='published'): ?><b class="badge"><?= e($model->status) ?></b><?php endif ?></div><h1><?= e($model->title) ?></h1><div class="meta"><b><?= e($model->author?->displayName??'球迷') ?></b><time><?= e($model->created_at) ?></time></div><div class="thread-body"><?= nl2br(e($model->body)) ?></div><?php if($model->match_id): ?><a href="/matches/<?= (int)$model->match_id ?>"><?= \app\services\TeamUi::label($model->match?->homeTeam) ?> <b><?= e($model->match?->home_score??'—') ?> : <?= e($model->match?->away_score??'—') ?></b> <?= \app\services\TeamUi::label($model->match?->awayTeam) ?> ↗</a><?php endif ?>
<div class="thread-actions"><?php if($user): ?><?php foreach(['like'=>[$liked,'♡ 点赞','♥ 已赞'],'bookmark'=>[$bookmarked,'＋ 收藏','✓ 已收藏']] as $kind=>[$active,$off,$on]): ?><form method="post" action="/forum/<?= (int)$model->id ?>/<?= e($kind) ?>"><?= csrf_field() ?><input type="hidden" name="enabled" value="<?= $active?'0':'1' ?>"><button class="button outline"><?= e($active?$on:$off) ?></button></form><?php endforeach ?><?php else: ?><a href="/login">登录点赞 / 收藏 →</a><?php endif ?><?php if($canEdit): ?><a href="/forum/<?= (int)$model->id ?>/edit">编辑主题</a><form method="post" action="/forum/<?= (int)$model->id ?>/delete" data-confirm="确定删除这个主题？"><?= csrf_field() ?><button class="text-button">删除主题</button></form><?php endif ?></div></article>
<section class="section replies"><h2><?= (int)$provider->totalCount ?> 条回复</h2><?php foreach($provider->models as $r): ?><article class="reply" id="reply-<?= (int)$r->id ?>"><div class="meta"><b><?= e($r->user?->displayName??'球迷') ?></b><time><?= e($r->created_at) ?></time><span>#<?= (int)$r->id ?></span></div><?php if($r->parent_id): ?><p class="quote-ref">回复 #<?= (int)$r->parent_id ?></p><?php endif ?><p><?= nl2br(e($r->body)) ?></p><?php if($user): ?><div class="reply-tools"><a href="#compose" data-quote="<?= (int)$r->id ?>">回复 TA →</a><?php if((int)$user->id===(int)$r->user_id||$user->isAdmin()): ?><details><summary>编辑</summary><form action="/forum/replies/<?= (int)$r->id ?>/edit" method="post"><?= csrf_field() ?><textarea name="body" required minlength="2" maxlength="10000"><?= e($r->body) ?></textarea><button class="button small">保存修改</button></form></details><form action="/forum/replies/<?= (int)$r->id ?>/delete" method="post" data-confirm="删除这条回复？"><?= csrf_field() ?><button class="text-button">删除</button></form><?php endif ?><details><summary>举报</summary><form action="/forum/<?= (int)$model->id ?>/report" method="post"><?= csrf_field() ?><input type="hidden" name="reply_id" value="<?= (int)$r->id ?>"><label>举报原因<input name="reason" required minlength="3" maxlength="500"></label><button class="button small">提交</button></form></details></div><?php endif ?></article><?php endforeach ?><?= yii\widgets\LinkPager::widget(['pagination'=>$provider->pagination]) ?><?php if(!$provider->models): ?><p class="empty">还没有回复，把你的观点留在这里。</p><?php endif ?></section>
<section id="compose" class="section"><h2>加入讨论</h2><?php if(!$user): ?><a href="/login" class="button">登录后回复 ↗</a><?php elseif($model->is_locked||$model->status!=='published'): ?><div class="empty">主题当前已锁定或未公开，暂停新增回复。</div><?php else: ?><form method="post" action="/forum/<?= (int)$model->id ?>/reply"><?= csrf_field() ?><?= Html::errorSummary($replyModel,['class'=>'form-errors']) ?><label>引用回复 ID（可选）<input type="number" name="parent_id" min="1" value="<?= e($replyModel->parent_id) ?>" data-parent-input></label><label>你的看法<textarea name="body" rows="5" minlength="2" maxlength="10000" required><?= e($replyModel->body) ?></textarea></label><button class="button">发布回复 ↗</button></form><?php endif ?></section></div>
<aside class="forum-sidebar"><h3>讨论管理</h3><p>有内容的讨论比立场更重要。发现问题内容，可以提交举报。</p><a href="/forum/new" class="button">发起新讨论 ↗</a><?php if($user): ?><details class="report-panel"><summary>举报此主题</summary><form method="post" action="/forum/<?= (int)$model->id ?>/report"><?= csrf_field() ?><label>原因<textarea name="reason" required minlength="3" maxlength="500" rows="3"></textarea></label><button class="button small">提交举报</button></form></details><?php endif ?></aside></div>
